def get_gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def get_lcm(a, b):
    return a * b // get_gcd(a, b)

def betweenTwoSets(arr1, arr2):
    lcm = get_lcm(arr1[0], arr2[0])
    for i in range(1, len(arr1)):
        lcm = get_lcm(lcm, arr1[i])
    for i in range(1, len(arr2)):
        lcm = get_lcm(lcm, arr2[i])
    return lcm

